  // Soft monthly-budget alert (Finding 3), best-effort.
  await maybeAlertBudget(server.userId);
  // KOL/Agency partner commission on this renewal charge (idempotent; best-effort).
  await accrueRecentCommissionsForCustomer(server.userId);

  // An UNPAID-suspended server springs back to life once paid — but only that
  // kind. This used to fire for ANY suspended server, so a customer suspended for
  // outbound abuse could click "Renew now", pay, and put themselves straight back
  // on the network, undoing an abuse or admin action with a card. Legacy rows with
  // a null `suspendReason` are not auto-lifted; an admin can clear those by hand.
  if (server.status === "SUSPENDED" && server.suspendReason === "UNPAID") {
    const pending = await db.job.count({
      where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
    });
    if (pending === 0) await db.job.create({ data: { type: "UNSUSPEND", serverId } });
  }
  revalidatePath(`/dashboard/servers/${serverId}`);
}

