export async function previewOrderCoupon(input: {
  planId: string;
  osTemplateId: string;
  termMonths?: number;
  dedicatedIp?: boolean;
  extraDiskGB?: number;
  couponCode: string;
}): Promise<{ ok: boolean; label?: string; discountCents?: number; error?: string }> {
  await requireUser();
  const code = String(input.couponCode ?? "").trim().toUpperCase();
  if (!code) return { ok: false, error: "Enter a code." };
  try {
    const quote = await orderQuote({
      planId: input.planId,
      osTemplateId: input.osTemplateId,
      hostname: "preview-host",
      termMonths: Number(input.termMonths ?? 1),
      dedicatedIp: !!input.dedicatedIp,
      extraDiskGB: input.extraDiskGB,
      couponCode: code,
    });
    if (quote.couponError) return { ok: false, error: quote.couponError };
    if (quote.couponDiscountCents > 0) return { ok: true, label: quote.couponLabel, discountCents: quote.couponDiscountCents };
    return { ok: false, error: "That code doesn’t apply to this order." };
  } catch (e) {
    if (e instanceof OrderError) return { ok: false, error: e.message };
    return { ok: false, error: "Couldn’t check that code. Try again." };
  }
}

/**
 * Grace added to a first-month-free hold's lifetime beyond the Checkout session's
 * payable window, so a payment landing at the very last instant still finds a live
 * hold to confirm. The `checkout.session.expired` webhook and the worker sweep only
 * reap holds past this, i.e. well after the session can no longer be paid.
 */
const RESERVATION_GRACE_MS = 10 * 60 * 1000;

export async function payAndDeploy(
  prev: any,
  formData: FormData,
): Promise<{ error?: string; checkout?: EmbeddedCheckout }> {
  const user = await requireUser();
  // Spend path: never move a customer's money while an admin is impersonating them.
  // Caught (not left to throw uncaught) so an impersonating admin sees this exact
  // message inline — the bare throw used to crash the whole page with a generic
  // "Something went wrong" screen instead, a real bug hit every time an admin
  // testing the wizard while impersonating tried to pay.
  try {
    await assertNotImpersonating();
  } catch (e) {
    return { error: e instanceof Error ? e.message : "This action is disabled while impersonating a customer." };
  }
  // Same verification gate every purchase path applies. This is the CARD path, so it is the
  // one where an unreachable address is most expensive: without it we would take
  // a real payment for a machine whose credentials have nowhere to go.
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };
  // Per-user server cap — the same one `orderGameServer` enforces for game tiers.
  const limitErr = await serverLimitError(user.id);
  if (limitErr) return { error: limitErr };
  const intent = intentFromFormData(formData);
  // Tag the order if the customer arrived via a partner deep link (?ref=kodely on
  // /dashboard/deploy, captured into a cookie by PartnerSourceCapture). Undefined
  // for a direct order, so it drops out of the Stripe-metadata JSON round-trip
  // like extraDiskGB/backupTier above.
  intent.partnerSource = partnerSourceFromCookie(await cookies());

  let quote;
  try {
    quote = await orderQuote(intent);
  } catch (e) {
    if (e instanceof OrderError) return { error: e.message };
    throw e;
  }

  // Managed first-month-free eligibility. If this account/IP has ALREADY redeemed
  // the promo (or it's switched off), re-quote at FULL price so the wallet split,
  // the card leg and the stamped total are all full — the free month is a
  // once-per-person offer. The wallet path is self-correcting regardless (its
  // atomic claim inside placeOrder charges full on a lost claim), but the CARD
  // leg settles up front, so it MUST be priced full here or a repeat customer
  // gets a second discounted checkout. This mirrors the coupon guard below.
  // `|| null` matters: hashIp returns "" when the IP is unavailable, and an empty
  // string is a REAL value to the (promoId, ipHash) unique — it would collide
  // across every IP-less redemption and wrongly block them. NULLs are distinct.
  const promoIpHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
  if (quote.promoCreditCents > 0 && !(await firstMonthFreeEligible(user.id, promoIpHash))) {
    quote = await orderQuote(intent, { suppressPromo: true });
  }
  const promoCampaign = promoCampaignFromCookie(await cookies());

  const isAdmin = user.role === "ADMIN";
  const freePath = !!intent.free && isAdmin;

  // Wallet-aware split. The customer's Review screen computes the exact same split
  // (lib/wallet-split.ts) from the same inputs, so what they see === what we charge.
  // `useWallet` defaults ON (only "0" turns it off) so existing forms keep applying
  // the balance. Free admin grants skip the split entirely (no money moves).
  const useWallet = formData.get("useWallet") !== "0";
  // VAT/GST for this customer (Finding 1), resolved from their billing country. The
  // rate is constant for the request; the tax cents track whatever net the quote
  // settles on after any promo/coupon re-quote below. The wallet split and the card
  // leg are computed from the TAX-INCLUSIVE total so the card is charged the same
  // total the customer is shown, and the stamped `OrderPrice` carries the tax so the
  // confirm route settles it without re-deriving. A free admin grant is never taxed.
  const taxCtx = freePath ? { ratePercent: 0, country: "", reverseCharged: false } : await taxContextForUser(user);
  const taxOn = (netCents: number) => Math.round((netCents * taxCtx.ratePercent) / 100);
  const dueWithTax = (netCents: number) => netCents + taxOn(netCents);
  // `let`: a first-month-free hold lost to a concurrent checkout forces a full-price
  // re-quote below, which changes the split. Free admin grants skip it entirely.
  let { walletApplied, cardCents } = freePath
    ? { walletApplied: 0, cardCents: 0 }
    : walletSplit({ dueCents: dueWithTax(quote.chargeCents), balanceCents: user.balanceCents, useWallet });

  // Card portion is $0 (free admin grant, or the wallet fully covers the charge) →
  // provision straight away. placeOrder debits the FULL chargeCents from the wallet
  // (or nothing, for a free grant); the balance check inside it holds because a
  // $0 card portion means balance >= chargeCents.
  if (freePath || cardCents <= 0) {
    let serverId: string;
    try {
      // Reuse the request-scoped IP hash computed above so placeOrder can enforce
      // both the coupon's once-per-person guard and the first-month-free 1/IP cap.
      serverId = await placeOrder(user, intent, null, { ipHash: promoIpHash, campaign: promoCampaign });
    } catch (e) {
      if (e instanceof OrderError) return { error: e.message };
      throw e;
    }
    // A wallet-only order is still a real payment (money left the balance) — stamp
    // the same `?purchase=1` marker the card/Stripe path gets via reportPurchase, so
    // ProvisioningOverlay's "just paid" signal covers this path too. Skip it for a
    // free admin grant (freePath): no money moved, nothing to celebrate.
    redirect(`/dashboard/servers/${serverId}${freePath ? "" : "?purchase=1"}`);
  }

  // RESERVE the first-month-free credit BEFORE opening the Checkout session. This is
  // the money-race fix: the card leg settles the discounted price up front, so unless
  // this account/IP's one credit is held EXCLUSIVELY here, two concurrent card
  // checkouts could each pass eligibility and each collect a free month from one
  // eligibility. The reserve's INSERT contends on the same two unique constraints as
  // the grant, so exactly one checkout holds it; a loser re-quotes at FULL price so
  // its stamped total, card leg and settlement all agree (displayed === charged). The
  // hold is CONFIRMED at fulfilment, RELEASED on `checkout.session.expired`, and
  // swept as a backstop — an abandoned checkout never permanently burns the offer.
  //
  // `promoCreditCents > 0` is the honest "this quote carries the free month" signal
  // (0 whenever the promo is off, already-redeemed via the re-quote above, or the
  // product is out of scope — firstMonthFreeAppliesTo). It is 0 for VPS today, so
  // this block is inert for VPS and correct the moment the owner extends the promo to
  // any card-checkout product.
  let promoReservationToken: string | null = null;
  if (quote.promoCreditCents > 0) {
    const reservedUntil = new Date(Date.now() + ORDER_CHECKOUT_EXPIRES_MS + RESERVATION_GRACE_MS);
    const res = await reserveFirstMonthFree({
      userId: user.id,
      ipHash: promoIpHash,
      serviceType: "VPS",
      campaign: promoCampaign,
      chargedCents: quote.chargeCents,
      reservedUntil,
    });
    if (res.reserved) {
      promoReservationToken = res.token;
    } else {
      // Lost the race (this account/IP already holds or redeemed the credit): re-quote
      // at FULL price and recompute the split so the card leg is the real full amount.
      quote = await orderQuote(intent, { suppressPromo: true });
      ({ walletApplied, cardCents } = walletSplit({ dueCents: dueWithTax(quote.chargeCents), balanceCents: user.balanceCents, useWallet }));
      // A full-price re-quote can be fully wallet-covered — provision immediately (its
      // own atomic claim inside placeOrder will correctly charge full on a lost claim).
      if (cardCents <= 0) {
        let serverId: string;
        try {
          serverId = await placeOrder(user, intent, null, { ipHash: promoIpHash, campaign: promoCampaign });
        } catch (e) {
          if (e instanceof OrderError) return { error: e.message };
          throw e;
        }
        redirect(`/dashboard/servers/${serverId}?purchase=1`);
      }
    }
  }

  // RESERVE the checkout coupon BEFORE opening the Checkout session — the money-race fix
  // (Finding 1). The card leg settles the DISCOUNTED price up front, so unless this
  // account/IP's slot (the two @@unique constraints) AND a global-cap slot
  // (`timesRedeemed` vs `maxRedemptions`) are held EXCLUSIVELY here, N concurrent card
  // checkouts could each pass an advisory read and each collect the discount while only
  // ONE redemption is recorded — defeating one-per-person/IP AND maxRedemptions. The
  // reserve's atomic increment + guarded INSERT means exactly one checkout holds it; a
  // loser DROPS the coupon and re-quotes at FULL price so the stamped total, card leg and
  // settlement all agree (never a discounted leg without a backing hold — displayed ===
  // charged). The hold is CONFIRMED at fulfilment, RELEASED on `checkout.session.expired`,
  // and swept as a backstop, so an abandoned checkout never permanently burns the coupon.
  //
  // Reached only on the TRUE card path (cardCents > 0 at this point): the free-admin and
  // wallet-covers-the-total paths above provision immediately via placeOrder, whose OWN
  // atomic `claimOrderCoupon` handles the coupon — so a coupon is never both reserved here
  // and claimed there. `promoIpHash` is the same request IP the promo reserve used, already
  // null-normalised (an empty string would collide across every IP-less redemption).
  let checkoutIntent = intent;
  let couponReservationToken: string | null = null;
  if (quote.couponId && quote.couponDiscountCents > 0) {
    const reservedUntil = new Date(Date.now() + ORDER_CHECKOUT_EXPIRES_MS + RESERVATION_GRACE_MS);
    const res = await reserveOrderCoupon({
      couponId: quote.couponId,
      maxRedemptions: quote.couponMaxRedemptions,
      firstTimeOnly: quote.couponFirstTimeOnly,
      userId: user.id,
      ipHash: promoIpHash,
      amountCents: quote.couponDiscountCents,
      reservedUntil,
    });
    if (res.reserved) {
      couponReservationToken = res.token;
    } else {
      // Lost the exclusive hold: drop the coupon and re-quote at FULL price, then recompute
      // the split. Full price can only be >= the discounted one, so the card leg stays > 0
      // (no immediate-provision path to re-enter). Preserve the current promo state — keep a
      // promo hold if one was taken, otherwise suppress (promo off / ineligible / N/A here).
      checkoutIntent = { ...intent, couponCode: undefined };
      quote = await orderQuote(checkoutIntent, { suppressPromo: !promoReservationToken });
      ({ walletApplied, cardCents } = walletSplit({ dueCents: dueWithTax(quote.chargeCents), balanceCents: user.balanceCents, useWallet }));
    }
  }

  // Card portion > 0 → charge ONLY the remainder on the card (not the full total).
  // On payment success the confirm route credits this card amount to the wallet and
  // then placeOrder debits the full chargeCents, so the wallet naturally absorbs
  // `walletApplied` and the card the rest — the wallet is never touched before the
  // card clears. (walletApplied is implied by cardCents vs. the recomputed charge,
  // so it needs no separate metadata field.)
  // The price is handed over EXPLICITLY, from the very quote the wallet split above
  // was computed from. Without this argument `createOrderCheckout` re-quotes
  // internally, microseconds later, from its own `new Date()` — the same function,
  // so no formula can drift, but two different instants. A promo boundary (or an
  // operator changing a plan price) falling between them would mean the card leg
  // and the stamped total were priced against two different worlds, and the wallet
  // would silently absorb the difference. One quote, one price, one charge.
  // If opening the session fails after we reserved, RELEASE both holds so the customer
  // never loses their offer (or the coupon's slot) to a checkout that never came into being.
  // `checkoutIntent` — not `intent` — so a coupon dropped on a lost reserve above is also
  // absent from the metadata fulfilment re-quotes from, matching the full-price `sold`.
  let checkout: EmbeddedCheckout | null;
  try {
    // Custom Checkout (ui_mode: "elements"), not the old embedded_page modal — the
    // card leg of the new embedded Payment step (components/customer/PaymentStep.tsx).
    // Identical params/metadata/promo-and-coupon-hold handling to
    // `createOrderCheckout`; see lib/stripe.ts's doc comment on why this is a pure
    // presentation change with zero fulfilment-path impact.
    checkout = await createOrderPaymentSession(
      user,
      cardCents,
      checkoutIntent,
      // Stamp the VAT the card leg was split from so fulfilment settles the SAME
      // tax-inclusive total — never re-derived after the card cleared.
      orderPriceOf(quote, { taxCents: taxOn(quote.chargeCents), ratePercent: taxCtx.ratePercent, country: taxCtx.country }),
      promoCampaign,
      promoReservationToken,
      couponReservationToken,
    );
  } catch (e) {
    if (promoReservationToken) await releaseReservation(promoReservationToken).catch(() => {});
    if (couponReservationToken) await releaseOrderCouponReservation(couponReservationToken).catch(() => {});
    throw e;
  }
  if (!checkout) {
    if (promoReservationToken) await releaseReservation(promoReservationToken).catch(() => {});
    if (couponReservationToken) await releaseOrderCouponReservation(couponReservationToken).catch(() => {});
    return { error: "Card payments aren't set up yet — top up your wallet to deploy." };
  }
  // The embedded session (clientSecret + publishableKey) for the modal on our page.
  return { checkout };
}

