export class OrderError extends Error {}

/**
 * Enforce the admin-configured per-user server cap (`max_servers_per_user`,
 * default 10; 0 = unlimited). Counts every server the user owns that isn't being
 * torn down (DELETING). Returns an error message when the cap is reached, else
 * null.
 *
 * Lives in this PLAIN module rather than lib/actions.ts (a `"use server"` file)
 * for the same reason `gameOrderGate` lives in lib/game-order.ts: it takes an
 * already-resolved `userId` and does no session check of its own, so exporting
 * it from a Server Actions file would let a stranger probe any account's server
 * count with no authentication — exactly the class of bug
 * test/auth-lockouts.test.ts's "HAZARD" suite exists to catch. `payAndDeploy`
 * (lib/actions.ts) and the PayPal/Coinbase VPS-order action
 * (lib/actions-payment-providers.ts) both call this AFTER their own
 * `requireUser()`.
 */
export async function serverLimitError(userId: string): Promise<string | null> {
  const cap = await getSettingInt("max_servers_per_user", 10);
  if (cap <= 0) return null; // 0 (or negative) = unlimited
  const owned = await db.server.count({ where: { userId, status: { notIn: ["DELETING"] } } });
  if (owned >= cap) {
    return `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}. Delete one or contact support to raise the cap.`;
  }
  return null;
}

