  osTemplateId: string;
  hostname: string;
  nodeId?: string;
  addonMalware?: boolean;
  addonBackup?: boolean;
  addonDocker?: boolean;
  termMonths?: number;
  dedicatedIp?: boolean;
  sshPublicKey?: string;
  sshKeyName?: string;
  free?: boolean;
  /**
   * Extra root-disk GB bought at deploy time, ON TOP of the plan's diskGB. The VM
   * is provisioned at plan.diskGB + extraDiskGB (worker/index.ts provision), so no
   * post-deploy expansion job is needed. Permanent — never shrinks.
   */
  extraDiskGB?: number;
  /** Checkout promo code (e.g. a "one free month" coupon), uppercased. */
  couponCode?: string;
  /**
   * Paid backup RETENTION tier bought at deploy time. FREE (included) or PLUS
   * (keep 7, priced monthly like the other add-ons). Round-tripped through Stripe
   * metadata, so it stays a tiny string.
