   * Stripe metadata like the other optional fields above, then persisted onto the
   * created Server row so worker/index.ts knows whether to notify the partner on
   * provision success — undefined (never the literal string) for a direct order.
   */
  partnerSource?: string;
};

/**
 * The price an order was SOLD at: the total, and the promo rate that produced it.
 * Fixed ONCE — before any money moves — and carried to the moment it is charged.
 *
 * REAL INCIDENT (2026-07-26 customer-journey rehearsal, H2). The card-paid deploy
 * path quoted a total, charged the CARD its share of that total at Stripe, and
 * then — on the confirm redirect, minutes or hours later — re-ran `orderQuote`
 * and debited whatever came back. That re-run includes `currentPromo(new Date())`,
 * and lib/promotions.ts always has an active sale that rotates by calendar date,
 * so a rotation between "customer clicked Deploy" and "customer came back from
 * Stripe" re-priced the order AFTER the card had cleared and took the difference
 * out of the wallet with no new consent. With no balance to take it from, the
 * payment was captured and no server was created.
 *
 * `lib/resize.ts` and `lib/disk-expand.ts` already carried the amount through
 * Stripe metadata for exactly this reason; the order path was the one that
 * re-derived it. Same rule as lib/renewal-quote.ts and lib/proration.ts: a figure
 * the customer was shown is not recomputed later, it is carried.
 *
 * `promoPercent` and `promoName` travel WITH the total because they are not
 * decoration. `Server.termPromoPercent` records the rate a term was actually sold
 * at (every later proration prices against it), and the promo name is the ledger
 * and invoice text the customer reads. Honouring a 30%-off price while stamping
 * today's 15% would hand every later proration the wrong basis and print a
 * discount on the invoice that does not match the money taken.
 */
export type OrderPrice = {
  /**
   * The NET (pre-tax) total the customer consented to, in cents. Its meaning is
   * unchanged by Finding 1 — every promo/coupon/proration figure is computed against
   * this net. The amount actually CHARGED is `chargeCents + (taxCents ?? 0)`.
   */
  chargeCents: number;
  /** Promo rate (%) that produced it; persisted as `Server.termPromoPercent`. */
  promoPercent: number;
  /** Promo name for the ledger / invoice line, e.g. "Summer Sale". */
  promoName: string;
  /**
   * VAT/GST on the net (Finding 1), carried through the card round-trip so the
   * confirm route settles the SAME tax-inclusive total the card leg was split from
   * — never re-derived after the card cleared. Absent on legacy/full-price sessions,
   * in which case the charge path recomputes it from the owner's country (0 by
   * default), which can only ever undertax, the conservative direction.
   */
  taxCents?: number;
  taxRatePercent?: number;
  taxCountry?: string;
};

/**
 * The sold price implied by a quote — the ONE place a quote becomes a price. An
 * optional resolved tax context stamps the VAT the card round-trip must settle.
 */
export function orderPriceOf(
  quote: {
    chargeCents: number;
    promo: { discountPercent: number; name: string };
  },
  tax?: { taxCents: number; ratePercent: number; country: string } | null,
): OrderPrice {
  return {
    chargeCents: quote.chargeCents,
    promoPercent: quote.promo.discountPercent,
    promoName: quote.promo.name,
    ...(tax
      ? { taxCents: tax.taxCents, taxRatePercent: tax.ratePercent, taxCountry: tax.country }
      : {}),
  };
}

/**
 * Parse a sold price back off Stripe metadata. Returns null unless EVERY field is
 * well-formed: a half-parsed price would be worse than no price at all, because
 * the caller's fallback (re-quote) is at least internally consistent.
 */
export function parseOrderPrice(raw: unknown): OrderPrice | null {
  let obj: unknown = raw;
  if (typeof raw === "string") {
    try {
      obj = JSON.parse(raw);
    } catch {
      return null;
    }
  }
  if (!obj || typeof obj !== "object") return null;
  const { chargeCents, promoPercent, promoName, taxCents, taxRatePercent, taxCountry } =
    obj as Record<string, unknown>;
  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
  if (typeof promoPercent !== "number" || !Number.isInteger(promoPercent)) return null;
  if (promoPercent < 0 || promoPercent > 100) return null;
  // Tax fields are ADDITIVE and lenient: a session written before Finding 1 (or with a
  // malformed tax field) carries none, and the charge path recomputes tax from the
  // owner's country — which undertaxes at worst, never overcharges.
  const tc = typeof taxCents === "number" && Number.isInteger(taxCents) && taxCents >= 0 ? taxCents : 0;
  const tr =
    typeof taxRatePercent === "number" && Number.isFinite(taxRatePercent) && taxRatePercent >= 0
      ? taxRatePercent
      : 0;
  return {
    chargeCents,
    promoPercent,
    promoName: typeof promoName === "string" ? promoName : "",
    taxCents: tc,
    taxRatePercent: tr,
    taxCountry: typeof taxCountry === "string" ? taxCountry : "",
  };
}

/** Extract a plain OrderIntent from a deploy form. */
export function intentFromFormData(formData: FormData): OrderIntent {
  return {
    planId: String(formData.get("planId") ?? ""),
    osTemplateId: String(formData.get("osTemplateId") ?? ""),
    hostname: String(formData.get("hostname") ?? ""),
    nodeId: String(formData.get("nodeId") ?? "") || undefined,
    addonMalware: formData.get("addon_malware") === "1",
    addonBackup: formData.get("addon_backup") === "1",
    addonDocker: formData.get("addon_docker") === "1",
    termMonths: Number(formData.get("termMonths") ?? 1),
    dedicatedIp: formData.get("dedicatedIp") === "1",
    sshPublicKey: String(formData.get("sshPublicKey") ?? "").trim() || undefined,
    sshKeyName: String(formData.get("sshKeyName") ?? "deploy-key").slice(0, 60),
    free: formData.get("free") === "1",
    // Rounded DOWN to a purchasable step — a malformed value can only ever cost
    // the customer less, never more. Left UNDEFINED (not 0) when nothing was
    // bought so it drops out of JSON.stringify: the intent is round-tripped
    // through Stripe metadata, which is capped at 500 chars (lib/stripe.ts
    // createOrderCheckout), and every byte of headroom matters there.
    extraDiskGB: normalizeExtraDiskGB(formData.get("extraDiskGB")) || undefined,
    couponCode: String(formData.get("couponCode") ?? "").trim().toUpperCase() || undefined,
    // Only PLUS is a paid choice; left UNDEFINED for FREE (the included tier) so it
    // drops out of the Stripe-metadata JSON round-trip, like extraDiskGB. orderQuote
    // re-normalizes undefined back to FREE.
    backupTier: normalizeBackupTier(formData.get("backup_tier")) === "PLUS" ? "PLUS" : undefined,
  };
}

