import { redirect } from "next/navigation";
import type { Role, User } from "@prisma/client";
import { realUser } from "./auth";

/**
 * Role-based access control for the admin ops portal.
 *
 * The admin surface is divided into logical *areas*. Each area maps to the set
 * of staff roles allowed to see and use it. ADMIN implicitly has every area.
 * The admin layout uses this to (a) let any staff role in and (b) hide nav
 * items a role can't reach; each sensitive page additionally gates itself with
 * `requireArea(...)` so a hand-typed URL is refused too.
 */
export type Area =
  | "overview"
  | "analytics"
  | "clients"
  | "support"
  | "fleet"
  | "billing"
  | "accounting"
  | "platform"
  // ---- Narrow areas carved out of "platform"/"support" so a specific tool
  // can be granted to a Role.EMPLOYEE (lib/staff-grants.ts) without opening
  // everything else those buckets also cover. Every OTHER route mapped to
  // "platform"/"support" is untouched — see lib/staff-grants.ts's doc
  // comment for why these six exist as their own areas instead of splitting
  // "platform"/"support" themselves. ADMIN (and, for supportTickets/liveChat,
  // SUPPORT) still reach these exactly as they reach any other area — only
  // EMPLOYEE needs an explicit StaffGrant to use them.
  | "redditTemplates"
  | "companyInbox"
  | "companyMailboxes"
  | "clientsBasic"
  | "supportTickets"
  | "liveChat"
  | "tasks";

/** Which roles may access each area. ADMIN is always allowed (see canAccess). */
export const AREA_ROLES: Record<Area, Role[]> = {
  overview: ["SUPPORT", "BILLING", "ADMIN"],
  analytics: ["ADMIN"],
  clients: ["SUPPORT", "ADMIN"],
  support: ["SUPPORT", "ADMIN"],
  fleet: ["ADMIN"],
  billing: ["BILLING", "ADMIN"],
  // Real cost/margin data (expenses, net income) — ADMIN only, unlike "billing"
  // (which BILLING-role staff also reach for day-to-day invoice/refund work).
  accounting: ["ADMIN"],
  platform: ["ADMIN"],
  redditTemplates: ["ADMIN"],
  companyInbox: ["ADMIN"],
  companyMailboxes: ["ADMIN"],
  clientsBasic: ["ADMIN"],
  // Identical role list to "support" — legacy SUPPORT-role behavior for
  // tickets/chat is unchanged; only EMPLOYEE needs a StaffGrant for these.
  supportTickets: ["SUPPORT", "ADMIN"],
  liveChat: ["SUPPORT", "ADMIN"],
  tasks: ["SUPPORT", "BILLING", "ADMIN"],
};

/**
 * Team invitations: consent tokens, plus who is entitled to see whom.
 *
 * WHY THIS MODULE NO LONGER EXPORTS `requireArea`
 * ----------------------------------------------
 * It used to export `requireArea(orgId, area)` — a page guard for "org-scoped
 * dashboard pages". There were none: `requireArea` had zero call sites in the
 * repo (AUDIT-24H rec. 47, QA-PRELAUNCH P1-19), `memberCanAccessHref` was
 * referenced only from its own docblock, and `Membership.areas` was write-only.
 * Meanwhile the Team UI rendered a checkbox per dashboard area and reported
 * "Access updated." So an owner who unticked everything except Invoices was
 * shown a restriction that no loader, action or route ever consulted. That is
 * the same defect class as the fake SSL certs and the migration that logged 4/4
 * with six domains dark, and it is the more dangerous shape of it: a security
 * control that reports success while enforcing nothing.
 *
 * Wiring it up for real would mean org-scoping every dashboard loader and every
 * server action that touches a server, domain, volume, invoice or ticket — none
 * of which live in this module's blast radius. A half-wired version (nav hidden,
 * loaders open) is strictly worse than none, because hiding a nav item looks
 * like enforcement. So the area system is deleted rather than faked, and this
 * module now carries the two things teams genuinely need in order to be safe.
 *
 * 1. INVITE TOKENS (consent). `inviteMember` used to create a Membership
 *    outright — the invitee never agreed to anything — and the team page then
 *    handed the inviter every co-member's `userId` and email. That is precisely
 *    the identity feed that made the unauthenticated 2FA oracle
 *    (`verifyTotpForUser`, QA-PRELAUNCH P0-2) targetable at a named account:
 *    type a victim's email, get back their internal id. Membership now requires
 *    the invitee to click Accept while signed in as the invited address.
 *
 * 2. `canAdministerOrg` — the single definition of "may administer membership",
 *    used both to authorise mutations and to decide whether a viewer is
 *    entitled to co-members' email addresses.
 *
 * Plain server-side module (no "use server"), so both the server actions and the
 * accept page can import these helpers. Nothing here is client-safe.
 */
import { createHash } from "node:crypto";
import { EncryptJWT, jwtDecrypt } from "jose";

/**
 * Invitation lifetime. Short on purpose: the token is the entire invitation
 * (see below), so expiry is the only thing that eventually retires a link the
 * sender regrets.
 */
export const INVITE_TTL_HOURS = 72;

/** What an invitation carries. `invitedBy` is re-checked at accept time. */
export type InviteClaims = {
  orgId: string;
  /** Lowercased email the invitation was addressed to. Binds the link to one person. */
  email: string;
  role: string;
  invitedBy: string;
};

/**
 * 256-bit key for the invite JWE, derived from AUTH_SECRET with an
 * invite-specific salt — the same derivation pattern as lib/terminal-token.ts.
 * The distinct salt means a session cookie can never be replayed as an
 * invitation (or vice-versa) even though both trace back to one secret.
 */
function inviteKey(): Uint8Array {
  const secret = process.env.AUTH_SECRET;
  if (!secret) throw new Error("AUTH_SECRET is not set — cannot issue team invitations");
  return new Uint8Array(createHash("sha256").update(`nxeon-org-invite:${secret}`).digest());
}

