/// A customer-defined inbound firewall (security-group) rule for a VPS.
///
/// Applied INSIDE the guest as iptables rules in the platform-owned NXEON_FW
/// chain (worker/firewall.ts), reconciled idempotently from the full rule set on
/// every change. `position` is the first-match precedence (iptables is
/// first-match-wins); `portFrom/portTo` are null for "all ports" and for
/// ICMP/ALL. Everything reaching a shell is validated + normalised by
/// lib/firewall-rules.ts first. `comment` is customer free text and never
/// touches the shell.
model FirewallRule {
  id         String            @id @default(cuid())
  serverId   String
  server     Server            @relation(fields: [serverId], references: [id], onDelete: Cascade)
  direction  FirewallDirection @default(INBOUND)
  action     FirewallAction
  protocol   FirewallProtocol
  portFrom   Int?
  portTo     Int?
  sourceCidr String?           @default("0.0.0.0/0")
  comment    String?
  enabled    Boolean           @default(true)
  position   Int               @default(0)
  createdAt  DateTime          @default(now())

  @@index([serverId])
}

model Job {
  id        String    @id @default(cuid())
  type      JobType
  status    JobStatus @default(QUEUED)
  payload   Json?
  error     String?
  progress  Int       @default(0) // 0..100 live task progress (backups/restores)
  step      String? // human-readable current step, e.g. "Creating archive… 42%"
  attempts  Int       @default(0)
  serverId  String?
  server    Server?   @relation(fields: [serverId], references: [id], onDelete: Cascade)
  createdAt DateTime  @default(now())
  updatedAt DateTime  @updatedAt
}

