import { db } from "./db";
import { pveFor } from "./proxmox";
import { effectiveDiskGB } from "./extra-disk";

/**
 * Host capacity accounting for the deploy flow.
 *
 * We oversell RAM (the scarce resource) by a factor, but never past the
 * host's physical RAM minus a reserve for the hypervisor itself. Disk on
 * `vmdata` is large relative to plan sizes, so RAM is the binding constraint.
 *
 * All values are overridable via env so staging/prod can differ without code
 * changes; the defaults match the production KS-GAME box (64 GB RAM).
 */
export const HOST_RAM_MB = Number(process.env.NXEON_HOST_RAM_MB ?? 64000);
export const HOST_RAM_RESERVE_MB = Number(process.env.NXEON_HOST_RAM_RESERVE_MB ?? 8000);
export const RAM_OVERSELL_FACTOR = Number(process.env.NXEON_RAM_OVERSELL ?? 1.5);

/**
 * Usable NVMe VM-disk pool in GB, used as a fallback when the live Proxmox
 * storage total can't be read. Unlike RAM we do NOT oversell disk — thin
 * provisioning already lets guests share the pool, so we commit against the
 * real pool size minus a safety margin.
 */
export const HOST_DISK_GB = Number(process.env.NXEON_HOST_DISK_GB ?? 800);
/** Fraction of usable disk we allow to be committed before refusing deploys. */
export const DISK_SAFETY_RATIO = Number(process.env.NXEON_DISK_SAFETY ?? 0.9);
/**
 * VM disk on ZFS is THIN-provisioned: a guest only consumes what it actually
 * writes, not its full nominal plan size. So committing raw plan sizes against
 * the pool wildly under-counts real capacity (e.g. four ~2 GB-used guests read
 * as 275 GB "committed"). We therefore oversell nominal disk like RAM, and rely
 * on the live free-space floor below as the true overflow guard.
 */
export const DISK_OVERSELL_FACTOR = Number(process.env.NXEON_DISK_OVERSELL ?? 3);
/** Refuse deploys once the pool's REAL free space would sit below this (GB). */
export const DISK_MIN_FREE_GB = Number(process.env.NXEON_DISK_MIN_FREE_GB ?? 20);

/** Effective committable RAM ceiling in MB after reserve + oversell. */
export function ramCeilingMB(): number {
  return Math.max(0, (HOST_RAM_MB - HOST_RAM_RESERVE_MB) * RAM_OVERSELL_FACTOR);
}

