 * touch `lastAutoBackup` — a null/stale value simply lets the sweep run the
 * first backup on its next pass.
 */
export async function setBackupSchedule(
  serverId: string,
  enabled: boolean,
  intervalHours: number
): Promise<{ error?: string }> {
