// ---------- 1b. Retry a failed provision ----------

/**
 * Re-enqueue provisioning for a server that failed to build (status ERROR).
 *
 * A terminal PROVISION failure strands the server in ERROR with a red banner and
 * no way forward; this is the customer's self-service retry. It re-uses the exact
 * same job/worker machinery as the original order — the provision handler keeps
 * any vmid already persisted on the row, so a retry resumes rather than leaking a
 * second VM. Ownership-checked, guarded to ERROR only, and respects the one
 * in-flight job invariant. Moving the row to PROVISIONING immediately makes the
 * detail page show the transitional "being set up" state (and auto-refresh)
 * rather than the stale ERROR banner while the worker picks the job up.
 */
export async function retryProvision(serverId: string): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);

  if (server.status !== "ERROR") {
    return { error: "This server isn't in a failed state." };
  }
  if (await hasInflightJob(serverId)) {
    return { error: "Another operation is already in progress on this server." };
  }

  await db.$transaction([
    db.server.update({
      where: { id: server.id },
      data: { status: "PROVISIONING", provisionError: null },
    }),
    db.job.create({ data: { type: "PROVISION", serverId } }),
  ]);
  await db.auditLog.create({
    data: { userId: user.id, action: "server.retry_provision", detail: serverId },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

// ---------- 2. Reinstall to a different OS ----------

/**
 * Switch the server to a different OS image and reinstall. This ERASES all data:
 * the worker's REINSTALL handler destroys the VM and re-provisions it from
 * `Server.osTemplateId`, so we persist the new template BEFORE enqueuing.
 */
export async function reinstallToOs(
  serverId: string,
  osTemplateId: string
): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);

  if (!["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped to reinstall." };
  }

  const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
  if (!os?.active) return { error: "That operating system isn't available." };
  if (os.id === server.osTemplateId) {
    return { error: "This server is already running that operating system." };
  }
  if (server.plan.ramMB < os.minRamMB) {
    return { error: `${os.name} needs at least ${os.minRamMB / 1024} GB RAM — your plan has ${server.plan.ramMB / 1024} GB.` };
  }
  if (server.plan.diskGB < os.minDiskGB) {
    return { error: `${os.name} needs at least ${os.minDiskGB} GB disk — your plan has ${server.plan.diskGB} GB.` };
  }

  if (await hasInflightJob(serverId)) {
    return { error: "Another operation is already in progress on this server." };
  }

  // A reinstall destroys and re-clones the VM (same vmid). Its disks — including
  // any block-storage volume disk (vm-<vmid>-disk-N) — are purged with it. A
  // *detached* volume still keeps its disk under this vmid (Proxmox "unused"), so
  // purge wipes it too. Refuse while ANY volume is pinned to this server so the
  // customer must delete it (which cleanly destroys just that disk) first.
  const pinnedVolumes = await db.volume.count({ where: { serverId } });
  if (pinnedVolumes > 0) {
    const n = pinnedVolumes === 1 ? "volume" : `${pinnedVolumes} volumes`;
    return {
      error:
        `This server still has ${pinnedVolumes === 1 ? "a" : pinnedVolumes} block-storage ${n}. ` +
        `Detaching isn't enough — the disk stays on this server, so a reinstall would erase it too. ` +
        `To KEEP the data, attach the ${pinnedVolumes === 1 ? "volume" : "volumes"} to a different server first; ` +
        `to discard it, delete the ${pinnedVolumes === 1 ? "volume" : "volumes"} from the Volumes page. Then reinstall.`,
    };
  }

  // Persist the target OS and enqueue the rebuild ATOMICALLY.
  //
  // The REINSTALL handler re-provisions from `Server.osTemplateId`, so the write
  // has to land before the job — but as two separate statements a failure between
  // them left the row claiming an operating system the VM is not running, with no
  // job to make it true. Every page, every support view and the next reinstall
  // would then read that row and believe it. One transaction: either the server
  // is recorded as the new image AND a rebuild is queued, or neither happened.
  await db.$transaction([
    db.server.update({ where: { id: server.id }, data: { osTemplateId: os.id } }),
    db.job.create({ data: { type: "REINSTALL", serverId } }),
  ]);
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "server.reinstall_os",
      detail: `${serverId} -> ${os.slug} (was ${server.osTemplate.slug})`,
    },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

// ---------- 3. Resize-down ----------

/**
 * Move a server to a SMALLER (cheaper) plan. CPU/RAM can shrink freely, but the
 * disk can NOT shrink on the hypervisor, so we require the target plan's disk to
 * be >= the current plan's disk (the worker's RESIZE handler hard-fails a shrink
 * otherwise). A prorated credit for the price difference over the remaining term
 * is returned to the wallet.
 */
