async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

/**
 * Set a customer-facing nickname (`Server.label`) shown as the primary name.
 * Passing an empty string clears the label (falls back to `Server.name`).
 * Validated (<= 40 chars, control chars stripped) and ownership-checked.
 */
export async function renameServer(
  serverId: string,
  label: string
): Promise<{ error?: string; label?: string | null }> {
  const { user } = await ownedServer(serverId);

  // Strip ASCII control characters, collapse whitespace, then trim.
  const clean = (label ?? "")
    .replace(/[\x00-\x1f\x7f]/g, "")
    .replace(/\s+/g, " ")
    .trim();
  if (clean.length > 40) return { error: "Name must be 40 characters or fewer." };
  const value = clean.length === 0 ? null : clean;

  await db.server.update({ where: { id: serverId }, data: { label: value } });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "server.rename",
      detail: `${serverId} -> ${value ?? "(cleared)"}`,
    },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { label: value };
}

