export async function customPlanFloor(): Promise<CustomPlanFloor> {
  const top = await db.plan.findFirst({
    where: { active: true, sortOrder: { lt: CATALOG_SORT_ORDER_CEILING } },
    orderBy: { priceCents: "desc" },
  });
  if (!top) throw new CustomPlanError("No base plan is configured yet — please contact support.");
  return {
    cpuCores: top.cpuCores,
    ramMB: top.ramMB,
    diskGB: top.diskGB,
    priceCents: top.priceCents,
    bandwidthTB: top.bandwidthTB,
  };
}

/** Admin-tunable platform-wide ceiling (lib/settings.ts custom_plan_max_*). */
export async function customPlanCeiling(): Promise<CustomPlanCeiling> {
  const [maxCpuCores, maxRamGB, maxDiskGB] = await Promise.all([
    getSettingInt("custom_plan_max_cpu_cores", CUSTOM_PLAN_DEFAULT_CEILING.maxCpuCores),
    getSettingInt("custom_plan_max_ram_gb", CUSTOM_PLAN_DEFAULT_CEILING.maxRamMB / 1024),
    getSettingInt("custom_plan_max_disk_gb", CUSTOM_PLAN_DEFAULT_CEILING.maxDiskGB),
  ]);
  return { maxCpuCores, maxRamMB: maxRamGB * 1024, maxDiskGB };
}

/** Admin-tunable per-unit rates. Disk reuses `extraDiskPerGbCents()` — the SAME
 *  $/GB the extra-disk upsell already charges on a premade plan — see the
 *  derivation comment on CUSTOM_PLAN_DEFAULT_RATES for why. */
export async function customPlanRates(): Promise<CustomPlanRates> {
  const [perVcpuCents, perRamGbCents, perDiskGbCents] = await Promise.all([
    getSettingInt("custom_plan_per_vcpu_cents", CUSTOM_PLAN_DEFAULT_RATES.perVcpuCents),
    getSettingInt("custom_plan_per_ram_gb_cents", CUSTOM_PLAN_DEFAULT_RATES.perRamGbCents),
    extraDiskPerGbCents(),
  ]);
  return { perVcpuCents, perRamGbCents, perDiskGbCents };
}

export type CustomPlanQuote =
  | { ok: true; floor: CustomPlanFloor; ceiling: CustomPlanCeiling; rates: CustomPlanRates; priceCents: number }
  | { ok: false; reason: string; floor: CustomPlanFloor; ceiling: CustomPlanCeiling };

/** Validate + price a custom spec without creating anything. Never throws — a bad
// price growth far more than CPU does, which matches lib/capacity.ts's own
// framing of RAM as "the scarce resource" the platform oversells carefully
// while CPU is comparatively cheap to add.)
//
// All three rates are admin-tunable via lib/settings.ts (`custom_plan_per_vcpu_cents`,
// `custom_plan_per_ram_gb_cents`; disk reuses the existing `extra_disk_gb_price_cents`)
// so the catalog can be retuned without a redeploy if the premade ladder ever moves.
export const CUSTOM_PLAN_DEFAULT_RATES: CustomPlanRates = {
  perVcpuCents: 11,
  perRamGbCents: 102,
  perDiskGbCents: 10, // mirrors extra_disk_gb_price_cents's shipped default
};

/** Sane platform-wide ceiling — deliberately generous (nothing in the premade
 *  catalog approaches this), but not infinite: a real physical node has to be
 *  able to hold it. Admin-tunable via lib/settings.ts (custom_plan_max_*). */
export const CUSTOM_PLAN_DEFAULT_CEILING: CustomPlanCeiling = {
  maxCpuCores: 32,
  maxRamMB: 128 * 1024,
  maxDiskGB: 2000,
};

